mutations.find:
min-width: 0;
flex: 0 3 auto;
/* Two lines, as before — French 「CONTRE-LA-MONTRE」 has always broken at its
   hyphens at 360px — and only past two lines an ellipsis. A single long word
   (「SOBREVIVÊNCIA」 at 320px) may break inside itself rather than push the
   buttons off the screen. */
display: -webkit-box;
-webkit-box-orient: vertical;
-webkit-line-clamp: 2;
overflow: hidden;
overflow-wrap: anywhere;
line-height: 1.2;

mutations.replace:
flex-wrap: wrap;
white-space: nowrap;
text-align: center;
